// Minimal Meteor Dash game targeting canvas with id="game"
// Ship moves horizontally at bottom, meteors fall from top.
// Collision ends the game.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // canvas not found
  const ctx = canvas.getContext('2d');
  // Set canvas size (you may adjust as needed)
  canvas.width = canvas.clientWidth || 800;
  canvas.height = canvas.clientHeight || 600;

  const ship = {
    width: 40,
    height: 20,
    x: canvas.width / 2 - 20,
    y: canvas.height - 30,
    speed: 5,
  };

  const meteors = [];
  const meteorSize = 30;
  const meteorSpeed = 2;
  const spawnInterval = 1000; // ms
  let lastSpawn = 0;
  let gameOver = false;

  const keys = { ArrowLeft: false, ArrowRight: false };

  function update(dt) {
    if (gameOver) return;
    // Move ship
    if (keys.ArrowLeft) ship.x -= ship.speed;
    if (keys.ArrowRight) ship.x += ship.speed;
    ship.x = Math.max(0, Math.min(canvas.width - ship.width, ship.x));

    // Spawn meteors
    if (performance.now() - lastSpawn > spawnInterval) {
      meteors.push({
        x: Math.random() * (canvas.width - meteorSize),
        y: -meteorSize,
        size: meteorSize,
      });
      lastSpawn = performance.now();
    }

    // Update meteors
    for (let i = meteors.length - 1; i >= 0; i--) {
      const m = meteors[i];
      m.y += meteorSpeed;
      // Remove off‑screen meteors
      if (m.y > canvas.height) meteors.splice(i, 1);
      // Collision detection (AABB)
      if (
        ship.x < m.x + m.size &&
        ship.x + ship.width > m.x &&
        ship.y < m.y + m.size &&
        ship.y + ship.height > m.y
      ) {
        gameOver = true;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Draw ship
    ctx.fillStyle = '#0f0';
    ctx.fillRect(ship.x, ship.y, ship.width, ship.height);
    // Draw meteors
    ctx.fillStyle = '#f00';
    meteors.forEach(m => {
      ctx.beginPath();
      ctx.arc(m.x + m.size / 2, m.y + m.size / 2, m.size / 2, 0, Math.PI * 2);
      ctx.fill();
    });
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    }
  }

  let lastTime = 0;
  function loop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // Input handlers
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
      keys[e.key] = true;
    }
  });
  window.addEventListener('keyup', e => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
      keys[e.key] = false;
    }
  });

  requestAnimationFrame(loop);
})();
